        else if(globalRank===2) price = 2356.00;
        else if(globalRank===100) price = 88.25;
        else price = Math.max(0.00001, (90000/(globalRank+2))*(0.6+rand()));
        const h1 = (rand()-0.52)*4;
        const h24 = (rand()-0.48)*14;
        const d7 = (rand()-0.5)*24;
        const mcap = globalRank===1 ? 1.51e12 : Math.max(2e7, price * (1e6 + rand()*2.5e8));
        const vol = globalRank===1 ? 284.35e9 : Math.max(1e6, mcap*(0.01+rand()*0.25));
        const supply = globalRank===1 ? '20.01M BTC' : `${(1 + rand()*980).toFixed(2)}M ${symbol}`;
        const series = Array.from({length:18}, () => 10 + rand()*80);
        rows.push({
          rank: globalRank,
          name, symbol, price, h1, h24, d7, mcap, vol, supply, series,
          category: categories[(globalRank-1)%categories.length],
          network: networks[(globalRank-1)%networks.length]
        });
      }
      return rows;
    }

    const state = {
      category: 'Top',
      network: 'All Networks',
      page: 1,
      hiddenCols: new Set(),
      minPrice: null,
      maxPrice: null,
      minMcap: null,
      change24h: 'all'
    };

    const tableBody = document.getElementById('tableBody');
    const pagesWrap = document.getElementById('pages');
    const pageInfo = document.getElementById('pageInfo');

    function sparkSVG(vals, positive=true){
      const w=130,h=34,p=2;
      const min=Math.min(...vals), max=Math.max(...vals), span=Math.max(1,max-min);
      const pts=vals.map((v,i)=>`${(i/(vals.length-1)*(w-p*2)+p).toFixed(1)},${(h-p-((v-min)/span)*(h-p*2)).toFixed(1)}`).join(' ');
      const color = positive ? '#16c784' : '#ea3943';
      return `<svg class="sparkline" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg"><polyline fill="none" stroke="${color}" stroke-width="2" points="${pts}"/></svg>`;
    }

    function filteredRows(rows){
      return rows.filter(r => {
        const catOk = state.category === 'Top' ? true : r.category === state.category;
        const netOk = state.network === 'All Networks' ? true : (state.network === 'More' ? !['Ethereum','BSC','Solana','Base'].includes(r.network) : r.network === state.network);
        const minP = state.minPrice == null || r.price >= state.minPrice;
        const maxP = state.maxPrice == null || r.price <= state.maxPrice;
        const minM = state.minMcap == null || r.mcap >= state.minMcap;
        const ch = state.change24h === 'all' || (state.change24h === 'gainers' ? r.h24 >= 0 : r.h24 < 0);
        return catOk && netOk && minP && maxP && minM && ch;
      });
    }

    function render(){
      const rows = filteredRows(generatePage(state.page));
      tableBody.innerHTML = '';

      const indexRow = document.createElement('tr');
      indexRow.innerHTML = `
        <td class="center" data-col="rank">—</td>
        <td data-col="name"><div class="coin"><span class="coin-badge" style="background:#dbeafe;color:#1d4ed8;">20</span><div class="coin-meta"><strong>CoinTracker 20 Index</strong><small>CT20</small></div></div></td>
        <td class="num" data-col="price">$154.29</td>
        <td class="num up" data-col="h1">+0.21%</td>
        <td class="num up" data-col="h24">+1.15%</td>
        <td class="num up" data-col="d7">+4.97%</td>
        <td class="num" data-col="mcap">—</td>
        <td class="num" data-col="vol">—</td>
        <td class="num" data-col="supply">—</td>
        <td class="center" data-col="spark">${sparkSVG([22,26,24,32,31,37,44,42,48,51,53,57,61], true)}</td>
      `;
      tableBody.appendChild(indexRow);

      rows.forEach(r=>{
        const tr = document.createElement('tr');
        const initials = r.symbol.slice(0,2);
        tr.innerHTML = `
          <td class="center" data-col="rank">${r.rank}</td>
          <td data-col="name"><div class="coin"><span class="coin-badge">${initials}</span><div class="coin-meta"><strong>${r.name}</strong><small>${r.symbol} · ${r.network}</small></div></div></td>
          <td class="num" data-col="price">${fmtUSD(r.price, r.price<1?4:2)}</td>
          <td class="num ${r.h1>=0?'up':'down'}" data-col="h1">${fmtPct(r.h1)}</td>
          <td class="num ${r.h24>=0?'up':'down'}" data-col="h24">${fmtPct(r.h24)}</td>
          <td class="num ${r.d7>=0?'up':'down'}" data-col="d7">${fmtPct(r.d7)}</td>
          <td class="num" data-col="mcap">${fmtCompact(r.mcap)}</td>
          <td class="num" data-col="vol">${fmtCompact(r.vol)}</td>
          <td class="num" data-col="supply">${r.supply}</td>
          <td class="center" data-col="spark">${sparkSVG(r.series, r.d7>=0)}</td>
        `;
        tableBody.appendChild(tr);
      });

      applyColumnVisibility();
      pageInfo.textContent = `Showing ${rows.length} assets · Page ${state.page} of 84`;
    }

    function applyColumnVisibility(){
      document.querySelectorAll('[data-col]').forEach(el=>{
        const c = el.getAttribute('data-col');
        el.style.display = state.hiddenCols.has(c) ? 'none' : '';
      });
    }

    function activateTabs(id, key){
      const wrap = document.getElementById(id);
      wrap.querySelectorAll('.tab').forEach(btn=>{
        btn.addEventListener('click', ()=>{
          wrap.querySelectorAll('.tab').forEach(b=>b.classList.remove('active'));
          btn.classList.add('active');
          state[key] = btn.dataset[key];
          render();
        });
      });
    }

    function renderPages(){
      pagesWrap.innerHTML='';
      const buttons = [1,2,3,4,'…',84];
      buttons.forEach(p=>{
        const b=document.createElement('button');
        b.className='page-btn'+(p===state.page?' active':'');
        b.textContent=p;
        if(typeof p==='number') b.addEventListener('click',()=>{state.page=p; render(); renderPages();});
        else b.disabled=true;
        pagesWrap.appendChild(b);
      });
    }

    function setupPromo(){
      const slides=[...document.querySelectorAll('.promo-slide')];
      let i=0;
      const show=n=>{slides.forEach(s=>s.classList.remove('active')); slides[n].classList.add('active');};
      document.getElementById('promoPrev').addEventListener('click',()=>{i=(i-1+slides.length)%slides.length; show(i);});
      document.getElementById('promoNext').addEventListener('click',()=>{i=(i+1)%slides.length; show(i);});
      setInterval(()=>{i=(i+1)%slides.length; show(i);}, 4500);
    }

    function setupPanels(){
      const columnsBtn=document.getElementById('columnsBtn');
      const filtersBtn=document.getElementById('filtersBtn');
      const columnsPanel=document.getElementById('columnsPanel');
      const filtersPanel=document.getElementById('filtersPanel');
      columnsBtn.addEventListener('click',()=>columnsPanel.classList.toggle('active'));
      filtersBtn.addEventListener('click',()=>filtersPanel.classList.toggle('active'));

      const cols=[['rank','Rank'],['name','Name'],['price','Price'],['h1','1h%'],['h24','24h%'],['d7','7d%'],['mcap','Market Cap'],['vol','Volume(24h)'],['supply','Circulating Supply'],['spark','7D Sparkline']];
      const container=document.getElementById('columnToggles');
      cols.forEach(([k,label])=>{
        const id='col_'+k;
        const wrapper=document.createElement('label');
        wrapper.innerHTML=`<input type="checkbox" id="${id}" checked> ${label}`;
        wrapper.querySelector('input').addEventListener('change',(e)=>{
          if(e.target.checked) state.hiddenCols.delete(k); else state.hiddenCols.add(k);
          applyColumnVisibility();
        });
        container.appendChild(wrapper);
      });

      document.getElementById('minPrice').addEventListener('input',e=>{state.minPrice=e.target.value?Number(e.target.value):null; render();});
      document.getElementById('maxPrice').addEventListener('input',e=>{state.maxPrice=e.target.value?Number(e.target.value):null; render();});
      document.getElementById('minMcap').addEventListener('input',e=>{state.minMcap=e.target.value?Number(e.target.value):null; render();});
      document.getElementById('change24hFilter').addEventListener('change',e=>{state.change24h=e.target.value; render();});
    }

    document.getElementById('readMoreBtn').addEventListener('click',()=>{
      const extra=document.getElementById('summaryExtra');
      extra.classList.toggle('active');
      document.getElementById('readMoreBtn').textContent = extra.classList.contains('active') ? 'Show Less' : 'Read More';
    });

    activateTabs('categoryTabs','category');
    activateTabs('networkTabs','network');
    setupPromo();
    setupPanels();
    render();
    renderPages();
  </script>
</body>
</html>
